log = []
def sub():
    try:
        yield 1
    except ValueError:
        log.append("sub-caught")
        yield 2
    finally:
        log.append("sub-finally")
def outer():
    try:
        yield from sub()
    finally:
        log.append("outer-finally")
it = outer()
next(it)
log.append(("throw-return", it.throw(ValueError("boom"))))
try:
    next(it)
except StopIteration:
    log.append("done")
print(log)

log = []
class C:
    def __enter__(self):
        log.append("enter")
        return "ctx"
    def __exit__(self, exc_type, exc_value, exc_tb):
        log.append(("exit", exc_type.__name__ if exc_type is not None else None))
        return True
try:
    with C() as value:
        log.append(("body", value))
        raise ValueError("boom")
    log.append("after")
except Exception as e:
    log.append(("escaped", type(e).__name__))
print(log)

